import{_ as a,o,c as t,a3 as i}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"运维与排查","description":"","frontmatter":{},"headers":[],"relativePath":"guide/go/operations.md","filePath":"guide/go/operations.md","lastUpdated":1789552132000}'),r={name:"guide/go/operations.md"};function d(l,e,n,c,s,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="运维与排查" tabindex="-1">运维与排查 <a class="header-anchor" href="#运维与排查" aria-label="Permalink to &quot;运维与排查&quot;">​</a></h1><h2 id="日志" tabindex="-1">日志 <a class="header-anchor" href="#日志" aria-label="Permalink to &quot;日志&quot;">​</a></h2><p>ApeAdmin-Gin 使用 Zap 输出结构化 JSON 日志。每个请求由 <code>request_id</code> 中间件分配唯一 ID，贯穿整个调用链路。操作日志通过异步队列（<code>auditqueue</code>）写入，不阻塞主请求。</p><p>MCP 调用自动记录审计日志，包含请求参数、响应结果、耗时和调用者信息，可在管理台查看。</p><p>排查问题时优先查看启动日志、插件状态、RequestID 对应的日志条目，以及浏览器 Network 中的 API 响应。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="菜单-404" tabindex="-1">菜单 404 <a class="header-anchor" href="#菜单-404" aria-label="Permalink to &quot;菜单 404&quot;">​</a></h3><p>检查菜单 <code>component</code> 是否能在 <code>frontend/src/views</code> 下找到同名 <code>.vue</code> 文件，大小写必须一致；然后退出管理台并重新加载用户菜单。</p><h3 id="插件接口不存在" tabindex="-1">插件接口不存在 <a class="header-anchor" href="#插件接口不存在" aria-label="Permalink to &quot;插件接口不存在&quot;">​</a></h3><p>检查插件 <code>Register()</code> 是否执行成功，查看启动日志中的插件加载阶段输出。L2 ZIP 插件需确认 manifest 清单格式正确。必要时先停用再重新启用。</p><h3 id="ai-对话失败" tabindex="-1">AI 对话失败 <a class="header-anchor" href="#ai-对话失败" aria-label="Permalink to &quot;AI 对话失败&quot;">​</a></h3><p>确认后台已配置 AI 模型 API Key 和网络访问；检查 MCP 网关超时设置（默认 30s）和并发限制（默认 10）。查看 MCP 审计日志中的错误详情。</p><h3 id="资源-404" tabindex="-1">资源 404 <a class="header-anchor" href="#资源-404" aria-label="Permalink to &quot;资源 404&quot;">​</a></h3><p>确认目标插件已启用，检查静态文件目录配置（<code>app.spa_dir</code>）和路由注册是否正常。</p><h2 id="生产检查清单" tabindex="-1">生产检查清单 <a class="header-anchor" href="#生产检查清单" aria-label="Permalink to &quot;生产检查清单&quot;">​</a></h2><ul><li>[ ] 修改 <code>jwt.secret</code>，否则密钥熔断机制拒绝启动（debug=false 时检测默认密钥）。</li><li>[ ] 调整数据库连接池 <code>max_open_conns</code> 匹配实际负载。</li><li>[ ] 确认 API 限流参数（每 IP 每分钟 300 次，burst 50）符合需求。</li><li>[ ] 配置 CORS Origins 为生产域名。</li><li>[ ] 验证优雅关闭流程：插件卸载 → 事件通知 → 日志 drain → DB 断连。</li><li>[ ] 为 <code>uploads/</code> 目录配置备份和访问控制。</li></ul>',16)])])}const _=a(r,[["render",d]]);export{u as __pageData,_ as default};
